import java.util.*;class Solution{int g(int a,int b){a=Math.abs(a);b=Math.abs(b);while(b!=0){int t=a%b;a=b;b=t;}return a;}public int maxPoints(int[][]p){int best=0;for(int i=0;i<p.length;i++){Map<String,Integer>m=new HashMap<>();int dup=1,local=0;for(int j=i+1;j<p.length;j++){int dx=p[j][0]-p[i][0],dy=p[j][1]-p[i][1];if(dx==0&&dy==0){dup++;continue;}int z=g(dx,dy);dx/=z;dy/=z;if(dx<0||dx==0&&dy<0){dx=-dx;dy=-dy;}String k=dx+"/"+dy;int c=m.getOrDefault(k,0)+1;m.put(k,c);local=Math.max(local,c);}best=Math.max(best,local+dup);}return best;}}
